// An unknown order, including ORD-8888, returns an empty result without
// throwing. Inspect the result to identify missing order data.
const ORDERS = {
  "ORD-1001": { orderId: "ORD-1001", amount: 49.99, currency: "USD", status: "settled" },
  "ORD-1002": { orderId: "ORD-1002", amount: 129.00, currency: "USD", status: "settled" }
};
const id = String(query || "").trim().toUpperCase();
const hit = ORDERS[id];
return hit ? JSON.stringify(hit) : "";
